    customersStep1Body: "Type a Danish CVR number (8 digits). We auto-fill the company name, address, and postal code from the public CVR + DAWA registers — saves you from typos that nullify a faktura.",
    customersStep2Title: "2. Private clients — no CVR",
    customersStep2Body: "Toggle off the B2B switch for privatpersoner. We still need a name and at least one of email or phone so the faktura has somewhere to land.",
    customersStep3Title: "3. Set sensible defaults",
    customersStep3Body: "Pick the customer's invoice language (DA / EN) so the PDF arrives in the right one. Set payment terms — Danish default is 8 dage netto. These pre-fill on every new faktura for this customer.",
    customersStep4Title: "4. Deletes are soft",
    customersStep4Body: "Customers tied to past invoices can't be hard-deleted (Bogføringsloven §10 needs the audit trail intact). We hide them from your list but keep them linked to historical fakturaer.",
    customersHowFooter: "CVR numbers are checked against CVR-registeret (Erhvervsstyrelsen). Addresses come from DAWA — Denmark's official address register.",
