    fakturaHowTitle: "How Faktura works",
    fakturaStep1Title: "1. Add a customer first",
    fakturaStep1Body: "Type a CVR and we auto-fill name + address from CVR/DAWA. For private clients, toggle Privatperson — no CVR needed.",
    fakturaStep2Title: "2. Create the invoice",
    fakturaStep2Body: "Add line items (description, qty, unit price). MOMS (25 % default) and totals calculate live. Save as draft to edit later.",
    fakturaStep3Title: "3. Send — PDF + mailto",
    fakturaStep3Body: "Click Send: the invoice locks, the PDF downloads, and your mail app opens pre-filled with the customer's email + subject + body. Attach the PDF and hit Send.",
    fakturaStep4Title: "4. Get paid — auto-matched",
    fakturaStep4Body: "Export your bank's CSV (2 clicks in netbank), upload it under Bank Import. BonBox auto-matches the payment to the open invoice within ±2 kr tolerance and flips status to Paid — no manual reconciliation.",
    fakturaHowFooter: "Faktura numbers run in sequence with no gaps, per branch per year. A sent faktura can't be deleted — cancel it with a kreditnota instead (we create it automatically).",
