    mileageDesc: "Track business trips · mileage allowance · auto-calculated deduction",
    mileageHowTitle: "How Mileage works",
    mileageStep1Title: "1. Log every business trip — same day",
    mileageStep1Body: "Date, km, purpose (e.g. \"supplier pickup — Grossisten\"), and your vehicle's registration. Skattestyrelsen requires contemporaneous logs — don't reconstruct trips at year-end.",
    mileageStep2Title: "2. Rate is auto-applied (2026)",
    mileageStep2Body: "First 20.000 km/year: 3,79 kr/km. Above 20.000 km: 2,23 kr/km. We freeze the rate on each entry, so even if Skattestyrelsen updates rates next year, your old entries stay accurate.",
    mileageStep3Title: "3. Watch the YTD card",
    mileageStep3Body: "Top card shows total km logged this year, your tax-deductible kroner, and which rate tier you're currently in. Most owners miss 10-15k kr/year by not tracking — this card makes it real.",
    mileageStep4Title: "4. Save your fuel receipts separately",
    mileageStep4Body: "The mileage allowance (kørselsgodtgørelse) replaces actual fuel/maintenance costs — you can't claim both. Keep receipts as documentation, but the deduction is calculated from the km log, not the receipts.",
    mileageHowFooter: "Rate per Skattestyrelsen's 2026 mileage allowance (befordringsgodtgørelse). The log must be kept as you go (Bogføringsloven §11) — you may be asked to document it in an audit.",
