    // Positioning — IS / IS NOT.
    landingPositioningTag: "Where it fits",
    landingPositioningTitle: "Not bookkeeping. Not POS. The layer on top.",
    landingPositioningSub: "BonBox is the morning-after close + AI brief that sits on top of whatever you already use. Keep your POS. Keep your bookkeeper. We do the part nobody else does.",
    landingPositioningIs: "BonBox is",
    landingPositioningIsNot: "BonBox is not",
    landingPosIs1: "The 30-second multi-terminal daily close",
    landingPosIs2: "Faktura with gap-less numbering",
