    landingPosIs4: "OCR receipts + bank-CSV auto-match to fakturaer",
    landingPosIs5: "CSV bundle for the årsregnskab, ready for your revisor to use as it is",
    landingPosNot1: "A POS terminal — keep yours, we sync from it",
    landingPosNot2: "A registered digital bookkeeping system — pair with one for SKAT filings",
    landingPosNot3: "A replacement for your revisor at årsregnskab time",
    landingPosNot4: "A payment processor — MobilePay / Stripe stay yours",
    landingPosNot5: "A spreadsheet — but it absorbs the busywork the spreadsheet was hiding",
    // FAQ. landingFaq2A2 drops the unbacked "save ~17,500 kr/yr" claim.
    landingFaqTag: "Questions",
    landingFaqTitle: "What people ask before signing up.",
    landingFaq1Q: "Does this work with my POS?",
    landingFaq1A: "BonBox doesn't replace your POS — it reads what comes out of it. Snap a photo of the kasserapport from any phone, BonBox extracts the numbers. Works regardless of which till you use, including paper kasserapport. (We don't have brand integrations — we OCR the Z-report, so any POS that prints one works.)",
    landingFaq2Q: "Do I still need an accountant?",
    landingFaq2A2: "Yes, for the årsregnskab and SKAT filings. BonBox handles the monthly grind (sales, faktura, bank-match, OCR receipts, MOMS tracking) so your revisor only needs you once a year.",
    landingFaq3Q: "What if the AI misreads a kasserapport?",
    landingFaq3A: "Every parsed receipt is editable — the AI suggests, you confirm. Low-confidence matches go to a Review inbox instead of the books. Nothing flips to 'final' without your tap. Plus a 10-year audit log records every change.",
    landingFaq4Q: "Where does my data live?",
    landingFaq4A: "The database is in Ireland. When a receipt needs reading, the image goes to Anthropic in the US. Every company that touches your data is named in the privacy policy.\n\nThe audit log can't be edited or deleted. That's locked in the database itself.\n\nYou can pull everything out as CSV and delete your account whenever you want.",
    landingFaq5Q: "Do I need a CVR to sign up?",
    landingFaq5A: "No. Sign up with email. Add CVR later when you want CVR-verified customers + auto-fill on fakturaer. Freelancers without a CVR work fine — just toggle 'Privatperson' on each customer.",
    landingFaq6Q: "What happens after the 14-day trial?",
    landingFaqMore: "Different question? Email",
