    landingAllSub: "BonBox replaces the spreadsheet glue between your POS and your bookkeeping. Every module shares the same data, so the morning Brief actually knows what you sold yesterday.",
    landingCatMoney1: "Sales tracking · Z-report capture",
    landingFreeF1: "Sales + Expenses + Daily Close",
    landingFaq6A: "You drop to Free automatically — no card, no auto-charge. Free keeps Sales + Expenses + Daily Close + the AI Brief forever. To unlock faktura + bank-match + brand-on-PDF, upgrade to Starter 199 kr/md (129 kr founding) or Pro 349 kr/md (249 kr founding), per business, no MOMS added — or stay on Free. Pricing is shown on this page; nothing is hidden.",
    landingFeature1Title: "Sales & Cash Flow", landingFeature1Desc: "Log sales in 2 taps. See revenue, profit, and cash flow — auto-synced to your cashbook in real-time.",
    landingFeature2Title: "Inventory & Stock", landingFeature2Desc: "Track stock levels, get low-stock alerts, sell items with auto-deduction. Pre-built templates for 21+ business types.",
    landingFeature3Title: "Bar Pour System", landingFeature3Desc: "Buy bottles in bulk, sell by glass. Auto-track pours, deduct stock, and log sales per drink.",
    landingFeature4Title: "Smart Staffing", landingFeature4Desc: "AI-powered shifts based on your busiest days + weather forecast. Right people, right time.",
    landingFeature5Title: "Business Health Score", landingFeature5Desc: "Get a score from 0-100. Profitability, consistency, cost control — at a glance.",
    landingFeature6Title: "Waste Tracker", landingFeature6Desc: "Log expired and wasted stock. See how much you're losing. Reduce waste, increase profit.",
    landingFeature7Title: "Weather Smart", landingFeature7Desc: "Rain = less foot traffic. See how weather affects your revenue and plan staff smarter.",
    landingFeature8Title: "Workshop Manager", landingFeature8Desc: "Job cards, vehicle tracking, parts & labor billing, mechanic leaderboard — built for auto workshops.",
    landingFeature9Title: "Multi-Business", landingFeature9Desc: "Run a café and a workshop under one login. Each branch gets its own type, nav, and daily close.",
